const items = $input.all();

const parsePossibleJson = (value) => {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  if (!trimmed) return null;

  try {
    return JSON.parse(trimmed);
  } catch (_) {
    const match = trimmed.match(/\{[\s\S]*\}/);
    if (!match) return null;
    try {
      return JSON.parse(match[0]);
    } catch (_) {
      return null;
    }
  }
};

const parseOutputObject = (current) => {
  let aiOutput = current?.output ?? current;

  if (typeof aiOutput === 'string') {
    aiOutput = parsePossibleJson(aiOutput) || { raw_text: aiOutput };
  }

  if (aiOutput && typeof aiOutput === 'object' && !Array.isArray(aiOutput) && typeof aiOutput.text === 'string') {
    const parsedFromText = parsePossibleJson(aiOutput.text);
    if (parsedFromText && typeof parsedFromText === 'object' && !Array.isArray(parsedFromText)) {
      aiOutput = { ...aiOutput, ...parsedFromText };
    }
  }

  if (typeof current?.text === 'string') {
    const parsedFromCurrentText = parsePossibleJson(current.text);
    if (parsedFromCurrentText && typeof parsedFromCurrentText === 'object' && !Array.isArray(parsedFromCurrentText)) {
      aiOutput = { ...(aiOutput || {}), ...parsedFromCurrentText };
    }
  }

  if (!aiOutput || typeof aiOutput !== 'object' || Array.isArray(aiOutput)) {
    aiOutput = { raw_output: aiOutput };
  }

  return aiOutput;
};

const safeAll = (nodeName) => {
  try {
    return $(nodeName).all().map((x) => x.json || {});
  } catch (_) {
    return [];
  }
};

const sourcePool = [
  ...safeAll('Keep Ad Image'),
  ...safeAll('No Image'),
  ...safeAll('Check if Has Image'),
  ...safeAll('Check if Video')
];

const pickSource = (item, index) => {
  const current = item.json || {};
  if (current.ad_id || current.brand || current.headline) return current;

  const pairIndex = item.pairedItem?.item;
  if (typeof pairIndex === 'number' && sourcePool[pairIndex]) {
    return sourcePool[pairIndex];
  }

  if (sourcePool[index]) return sourcePool[index];

  return {};
};

return items.map((item, index) => {
  const current = item.json || {};
  const source = pickSource(item, index);
  const aiOutput = parseOutputObject(current);

  return {
    json: {
      ...source,
      ...current,
      output: aiOutput,
      hook_type: aiOutput.hook_type ?? source.hook_type ?? current.hook_type ?? '',
      why_it_works: aiOutput.why_it_works ?? source.why_it_works ?? current.why_it_works ?? '',
      takeaway_1: aiOutput.takeaway_1 ?? source.takeaway_1 ?? current.takeaway_1 ?? '',
      takeaway_2: aiOutput.takeaway_2 ?? source.takeaway_2 ?? current.takeaway_2 ?? '',
      takeaway_3: aiOutput.takeaway_3 ?? source.takeaway_3 ?? current.takeaway_3 ?? '',
      hook_de_sortie: aiOutput.hook_de_sortie ?? source.hook_de_sortie ?? current.hook_de_sortie ?? '',
      tunnel_friction_reasons: aiOutput.tunnel_friction_reasons ?? source.tunnel_friction_reasons ?? current.tunnel_friction_reasons ?? '',
      tunnel_recommendations: aiOutput.tunnel_recommendations ?? source.tunnel_recommendations ?? current.tunnel_recommendations ?? ''
    }
  };
});

return $input.all().map((item) => {
  const binaryData = item.binary?.data;

  if (!binaryData) {
    return { json: item.json || {} };
  }

  return {
    json: item.json || {},
    binary: {
      data: {
        ...binaryData,
        mimeType: 'video/mp4',
        fileExtension: 'mp4',
        fileName: binaryData.fileName || 'video.mp4'
      }
    }
  };
});

